<?php if(!isset($db) || !canIssue()){http_response_code(403);exit;}
$status=$_GET['status']??'pending';if(!in_array($status,['pending','approved','rejected'],true))$status='pending';
$total=(int)rows('SELECT COUNT(*) n FROM certificate_requests WHERE status=?',[$status])[0]['n'];$pages=max(1,(int)ceil($total/30));$pageNo=max(1,min($pages,(int)($_GET['p']??1)));$offset=($pageNo-1)*30;
?>
<?=numberingStatus()?>

<div class="page-heading"><div><h1>พิจารณาคำร้องขอเลขที่</h1><p class="muted">อนุมัติแล้วจึงออกเลขกลาง • คำร้องเดิมออกเลขได้ครั้งเดียว</p></div><a class="button secondary" href="?page=request">แบบฟอร์มคำร้อง</a></div><div class="tabs"><?php foreach(['pending'=>'รอพิจารณา','approved'=>'อนุมัติแล้ว','rejected'=>'ไม่อนุมัติ'] as $key=>$label):?><a class="<?=$status===$key?'selected':''?>" href="?page=requests&status=<?=$key?>"><?=$label?></a><?php endforeach ?></div>
<?php foreach(rows('SELECT * FROM certificate_requests WHERE status=? ORDER BY id DESC LIMIT 30 OFFSET '.$offset,[$status]) as $r):?><section class="card"><h2>REQ-<?=str_pad((string)$r['id'],6,'0',STR_PAD_LEFT)?> · <?=e($r['title'])?></h2><p><?=e($r['requester'])?> · <?=e($r['department'])?> · <?=(int)$r['quantity']?> เลข</p><p class="multiline"><?=e($r['purpose'])?></p><a class="text-link" target="_blank" href="?page=request&token=<?=e($r['token'])?>">ตรวจรายละเอียด / จำนวนเลข / พิมพ์คำร้อง ↗</a><?php if($status==='pending'):?><form method="post"><?=csrf()?><input type="hidden" name="action" value="review_request"><input type="hidden" name="request_id" value="<?=$r['id']?>"><label>หมายเหตุ / เหตุผล (จำเป็นเมื่อไม่อนุมัติ)<textarea name="review_note" rows="2" maxlength="2000"></textarea></label><button name="decision" value="approved">อนุมัติและออกเลขที่</button> <button class="secondary" name="decision" value="rejected">ไม่อนุมัติ</button></form><?php else:?><p><?=e($r['review_note'])?></p><?php endif ?></section><?php endforeach ?>
<?php if(!$total):?><div class="card empty">ไม่มีคำร้องในสถานะนี้</div><?php endif ?><p>หน้า <?=$pageNo?> / <?=$pages?></p><?php if($pageNo>1):?><a class="button secondary" href="?page=requests&status=<?=$status?>&p=<?=$pageNo-1?>">← ก่อนหน้า</a><?php endif ?> <?php if($pageNo<$pages):?><a class="button secondary" href="?page=requests&status=<?=$status?>&p=<?=$pageNo+1?>">ถัดไป →</a><?php endif ?>
